-- +goose Up
-- An Automation version holds its Steps as a root path of typed Steps with ids (ADR 0122), an
-- Enrollment, an Automation message and a figure name a Step by its id, and every Step an
-- Enrollment reaches leaves a Step record (ADR 0124). The project carries no legacy (ADR 0047): no
-- stored version, Enrollment, figure or Automation message is carried over, so a database that holds
-- one is refused before a column goes; it is reset (`mise run db:reset`). It rides Major 4, the
-- Major of the collapsed history, which no release has shipped. ent's diff wrote the DDL; the guard,
-- the changed CHECKKs and the NOT VALID constraints the next migration (20261122135745) validates
-- are written by hand.
-- +goose StatementBegin
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM "automation_versions")
    OR EXISTS (SELECT 1 FROM "automation_figures")
    OR EXISTS (SELECT 1 FROM "outbound_messages" WHERE "kind" = 'automation') THEN
    RAISE EXCEPTION 'the database holds Automations whose Steps have no ids (ADR 0122): reset it, the project carries no legacy (ADR 0047)';
  END IF;
END
$$;
-- +goose StatementEnd
-- modify "automation_versions" table
ALTER TABLE "automation_versions" DROP CONSTRAINT "automation_versions_steps_check";
ALTER TABLE "automation_versions" ALTER COLUMN "steps" DROP DEFAULT;
ALTER TABLE "automation_versions" ADD CONSTRAINT "automation_versions_steps_check" CHECK (COALESCE((jsonb_typeof((steps -> 'steps'::text)) = 'array'::text), false)) NOT VALID;
-- modify "automation_figures" table
ALTER TABLE "automation_figures" DROP COLUMN "step", ADD COLUMN "step_id" character varying NOT NULL, ADD COLUMN "version_id" bigint NOT NULL;
ALTER TABLE "automation_figures" ADD CONSTRAINT "automation_figures_automation_versions_version" FOREIGN KEY ("workspace_id", "version_id") REFERENCES "automation_versions" ("workspace_id", "id") ON UPDATE NO ACTION ON DELETE NO ACTION NOT VALID;
-- modify "automation_runs" table
ALTER TABLE "automation_runs" DROP COLUMN "current_step", ADD COLUMN "current_step_id" character varying NULL;
-- create "automation_step_records" table
CREATE TABLE "automation_step_records" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, "step_id" character varying NOT NULL, "reached_at" timestamptz NOT NULL, "left_at" timestamptz NULL, "outcome" character varying NULL, "skip_reason" character varying NULL, "due_at" timestamptz NULL, "run_id" bigint NOT NULL, "workspace_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "automation_step_records_automation_runs_run" FOREIGN KEY ("workspace_id", "run_id") REFERENCES "automation_runs" ("workspace_id", "id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "automation_step_records_workspaces_automation_step_records" FOREIGN KEY ("workspace_id") REFERENCES "workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "automation_step_records_left_check" CHECK ((left_at IS NULL) = (outcome IS NULL)), CONSTRAINT "automation_step_records_outcome_check" CHECK ((outcome)::text = ANY ((ARRAY['done'::character varying, 'skipped'::character varying])::text[])), CONSTRAINT "automation_step_records_reason_check" CHECK ((outcome IS NOT NULL) OR (skip_reason IS NULL)), CONSTRAINT "automation_step_records_skip_reason_check" CHECK ((skip_reason)::text = ANY ((ARRAY['suppressed'::character varying, 'unsubscribed_everything'::character varying, 'unsubscribed_source'::character varying, 'unconfirmed'::character varying, 'no_destination'::character varying, 'contact_erased'::character varying, 'no_local_time'::character varying, 'frequency_cap'::character varying])::text[])), CONSTRAINT "automation_step_records_skipped_check" CHECK ((((outcome)::text = 'done'::text) AND (skip_reason IS NULL)) OR (((outcome)::text = 'skipped'::text) AND (skip_reason IS NOT NULL))));
-- create index "automation_step_records_workspace_id_run_id_step_id" to table: "automation_step_records"
CREATE UNIQUE INDEX "automation_step_records_workspace_id_run_id_step_id" ON "automation_step_records" ("workspace_id", "run_id", "step_id");
-- modify "outbound_messages" table: the provenance CHECK names the columns that replace the Step's
-- position, so it goes before the column it names and comes back over the new ones.
ALTER TABLE "outbound_messages" DROP CONSTRAINT "outbound_messages_provenance_check";
ALTER TABLE "outbound_messages" DROP COLUMN "automation_step", ADD COLUMN "automation_step_id" character varying NULL, ADD COLUMN "automation_version_id" bigint NULL;
ALTER TABLE "outbound_messages" ADD CONSTRAINT "outbound_messages_provenance_check" CHECK ((kind = 'broadcast' AND broadcast_id IS NOT NULL AND automation_id IS NULL AND automation_version_id IS NULL AND automation_step_id IS NULL AND automation_run_id IS NULL AND template_id IS NULL) OR (kind = 'automation' AND automation_id IS NOT NULL AND automation_version_id IS NOT NULL AND automation_step_id IS NOT NULL AND broadcast_id IS NULL AND broadcast_recipient_id IS NULL AND template_id IS NULL) OR (kind = 'transactional' AND broadcast_id IS NULL AND broadcast_recipient_id IS NULL AND automation_id IS NULL AND automation_version_id IS NULL AND automation_step_id IS NULL AND automation_run_id IS NULL)) NOT VALID;
ALTER TABLE "outbound_messages" ADD CONSTRAINT "outbound_messages_automation_versions_automation_version" FOREIGN KEY ("workspace_id", "automation_version_id") REFERENCES "automation_versions" ("workspace_id", "id") ON UPDATE NO ACTION ON DELETE RESTRICT NOT VALID;

